// telegram_check.py passes one Telegram message as JSON in TG_MESSAGE.
// Only the chat in TELEGRAM_CHAT_ID may start uploads; anything else is ignored.
let msg = {};
try { msg = JSON.parse($env.TG_MESSAGE || '{}'); } catch (e) { msg = {}; }
const allowed = String($env.TELEGRAM_CHAT_ID || '').trim();
const chatId = String((msg.chat && msg.chat.id) ?? '');
if (!allowed || chatId !== allowed) return [];

// First line of the message, without the quotes Explorer's "Copy as path" adds.
// intake.py gets the whole message: a word like "public" may follow the path.
const text = String(msg.text || '').trim();
const firstLine = text.split(/\r?\n/)[0].trim();
const path = firstLine.replace(/^["'“”‘’]+|["'“”‘’]+$/g, '').trim();
const isPath = /^[a-z]:[\\/]/i.test(path) || /^\\\\/.test(path) || /^(~|%\w+%|file:\/\/\/)/i.test(path);

// The message reaches the shell only as hex (UTF-8), so quotes, & or % in it cannot run anything
const pathHex = encodeURIComponent(text).replace(/%([0-9A-F]{2})|([\s\S])/g,
  (m, h, c) => (h ? h.toLowerCase() : c.charCodeAt(0).toString(16).padStart(2, '0')));

return [{ json: {
  chatId,
  messageId: msg.message_id,
  isPath,
  path,
  pathHex,
  repo: String($env.N8N_YT_REPO || '').split('\\').join('/'),
  python: $env.PYTHON || 'python',
} }];

// intake.py prints one JSON object on stdout; its logs go to stderr
const { stdout, stderr, exitCode } = $input.first().json;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
let r;
try {
  r = JSON.parse(String(stdout || '').trim().split(/\r?\n/).pop());
} catch (e) {
  r = { ok: false, error: `intake.py returned no result (exit ${exitCode}): ${String(stderr || '').slice(-300)}` };
}
if (!r.ok) {
  return [{ json: { ok: false, error: r.error, errorText: `❌ <b>Nothing uploaded.</b>\n${esc(r.error)}` } }];
}

const missing = r.missing || [];
const model = $env.OLLAMA_MODEL || 'gemma4:latest';
const field = (key, extra = '') => missing.includes(key)
  ? '➖ missing, the local LLM writes it'
  : (r.field_source || {})[key] === 'app' ? `✅ typed in the app${extra}` : `✅ from ${esc(r.meta_file)}${extra}`;
const thumbs = (r.thumbnails || []).map((t) => `${t.label} = ${esc(t.name)}`).join(', ') || 'none, YouTube picks a frame';
const rl = r.related || {};
const linked = (rl.mode === 'video' ? esc(rl.video_id) : rl.mode === 'latest' ? 'latest long video on the channel' : 'none')
  + (rl.source ? ` (${esc(rl.source)})` : '');
const lines = [
  `📂 <b>${esc(r.file_name)}</b>`,
  `${r.is_short ? 'Short' : 'Video'} · ${Math.round(r.duration_s)} s · ${r.size_mb} MB · channel ${esc(r.channel)}`,
  '',
  `<i>Title:</i> ${field('title')}`,
  `<i>Description:</i> ${field('description')}`,
  `<i>Tags:</i> ${field('tags', ` (${(r.tags || []).length})`)}`,
  `<i>Thumbnails:</i> ${thumbs}`,
  `<i>Linked video:</i> ${linked}`,
  `<i>Visibility:</i> ${r.publish_at ? `private until ${esc(r.publish_at_local)}, then public` : esc(r.privacy)} (${esc(r.privacy_source)})`,
  ...(r.warnings || []).map((w) => `⚠️ ${esc(w)}`),
  '',
  (missing.length ? `Next: transcribe, let ${esc(model)} write the missing parts (1 to 2 minutes), then upload` : 'Next: upload')
    + (r.publish_at ? `, set the thumbnail, then schedule it for ${esc(r.publish_at_local)}.`
      : r.privacy === 'private' ? ' as private.' : `, set the thumbnail, then make it ${esc(r.privacy)}.`),
];
return [{ json: { ...r, statusText: lines.join('\n') } }];

const { stdout, stderr, exitCode } = $input.first().json;
let result;
try {
  result = JSON.parse(String(stdout || '').trim().split(/\r?\n/).pop());
} catch (e) {
  throw new Error(`transcribe.py returned no JSON (exit ${exitCode}): ${String(stderr || '').slice(-400)}`);
}
if (!result.ok) throw new Error(`Transcription failed: ${result.error}`);
return [{ json: { transcript: result.transcript } }];

