// Fields from the text file win; the LLM only fills the gaps. YouTube's limits apply to both.
const it = $('Parse intake').first().json;
const ch = $('Parse channel config').first().json.data;
const ran = (name) => { try { return $(name).isExecuted; } catch (e) { return false; } };
const ai = ran('Write missing metadata (local LLM)')
  ? ($('Write missing metadata (local LLM)').first().json.output || {})
  : {};

const oneLine = (s) => String(s ?? '').replace(/[<>]/g, '').replace(/\s+/g, ' ').trim();
const bytes = (s) => encodeURIComponent(s).replace(/%[0-9A-F]{2}/gi, 'x').length;
const fold = (s) => s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase(); // 'café' == 'cafe'
const source = {};

// Title: max 100 characters, no angle brackets (YouTube rejects them)
const fs = it.field_source || {};  // 'app' = typed in the desktop app, 'file' = meta.txt
let title = oneLine(it.title);
source.title = fs.title === 'app' ? 'app' : 'file';
if (!title) { title = oneLine(ai.title) || it.base_name; source.title = 'llm'; }
if (title.length > 100) title = title.slice(0, 99).replace(/\s+\S*$/, '') + '…';

// Description: the uploader's text as written; a generated one gets chapters, hashtags and the channel footer
let description;
if (it.description) {
  description = String(it.description).replace(/[<>]/g, '').trim();
  source.description = fs.description === 'app' ? 'app' : 'file';
} else {
  const parts = [String(ai.description || '').replace(/[<>]/g, '').trim()];
  const chapters = Array.isArray(ai.chapters) ? ai.chapters : [];
  if (!it.is_short && chapters.length >= 3 && /^0?0:00$/.test(String(chapters[0].time).trim())) {
    parts.push(chapters.map((c) => `${String(c.time).trim()} ${oneLine(c.title)}`).join('\n'));
  }
  if (ch.hashtags?.length) parts.push(ch.hashtags.join(' '));
  if (ch.description_footer) parts.push(ch.description_footer);
  description = parts.filter(Boolean).join('\n\n');
  source.description = 'llm';
}
// Linked video at the top of the description (Shorts: the latest long video by default)
const link = ran('Pick linked video') ? $('Pick linked video').first().json : null;
if (link && link.ok && !description.includes(link.id)) {
  const lang = String(ch.metadata_language || '').slice(0, 2);
  const label = ch.related_label
    || ({ es: '▶ Video completo', de: '▶ Ganzes Video', pt: '▶ Vídeo completo', fr: '▶ Vidéo complète' }[lang] || '▶ Full video');
  const head = (oneLine(link.title) ? `${label}: ${oneLine(link.title)}` : `${label}:`) + `\n${link.url}`;
  description = [head, description].filter(Boolean).join('\n\n');
}
while (bytes(description) > 5000) description = description.slice(0, -50);  // cuts the end, the link stays

// Tags: the uploader's list, or channel defaults + LLM tags; YouTube counts quotes around
// tags with spaces and the commas between them, total max 500 characters
const fromFile = (it.tags || []).length > 0;
source.tags = fromFile ? (fs.tags === 'app' ? 'app' : 'file') : 'llm';
const tagList = [];
let budget = 0;
for (const raw of fromFile ? it.tags : [...(ch.default_tags || []), ...(ai.tags || [])]) {
  const tag = oneLine(raw).replace(/[,#]/g, '').slice(0, 60);
  if (!tag || tagList.some((x) => fold(x) === fold(tag))) continue;
  const cost = tag.length + (tag.includes(' ') ? 2 : 0) + (tagList.length ? 1 : 0);
  if (budget + cost > 480) break;
  tagList.push(tag);
  budget += cost;
}

const thumbs = it.thumbnails || [];
return [{
  json: {
    channel: it.channel,
    channelName: ch.display_name || it.channel,
    fileName: it.file_name,
    videoPath: it.video_path,
    isShort: it.is_short,
    duration: it.duration_s,
    title,
    description,
    tagList,
    tags: tagList.join(','),
    source,
    model: $env.OLLAMA_MODEL || 'gemma4:latest',
    metaFile: it.meta_file,
    thumbA: thumbs[0] || null,
    thumbB: thumbs[1] || null,
    privacy: it.privacy || 'private',
    privacySource: it.privacy_source || 'default',
    related: link
      ? { ok: Boolean(link.ok), id: link.id || null, title: link.title || '', url: link.url || null,
          mode: link.mode, source: link.source, note: (link.ok ? link.warning : link.reason) || null }
      : { ok: false, mode: (it.related || {}).mode || 'none', source: (it.related || {}).source || '' },
    publishAt: it.publish_at || null,
    publishAtLocal: it.publish_at_local || null,
    categoryId: String(ch.category_id || '22'),
    defaultLanguage: ch.metadata_language || 'en',
    madeForKids: Boolean(ch.made_for_kids),
  },
}];

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const ran = (name) => { try { return $(name).isExecuted; } catch (e) { return false; } };
const m = $('Final metadata').first().json;
const videoId = $('Upload to YouTube (private)').first().json.uploadId;
const studio = `https://studio.youtube.com/video/${videoId}/edit`;
const watch = `https://youtu.be/${videoId}`;
const from = (key) => (m.source[key] === 'app' ? 'typed in the app'
  : m.source[key] === 'file' ? `from ${esc(m.metaFile)}` : `written by ${esc(m.model)}`);

let thumbA = 'none in the folder, YouTube picks a frame';
if (m.thumbA) {
  const res = ran('Set thumbnail A') ? $('Set thumbnail A').first().json : {};
  thumbA = res.error
    ? `${esc(m.thumbA.name)} NOT set: ${esc(String(res.error.message || res.error).slice(0, 150))}`
    : `${esc(m.thumbA.name)} set`;
}
let thumbB = null;
if (m.thumbB) {
  thumbB = m.isShort
    ? `${esc(m.thumbB.name)} not used, YouTube has no thumbnail A/B test for Shorts`
    : `${esc(m.thumbB.name)}: the API sets one thumbnail only, so add A and B in YouTube Studio under A/B testing`;
}
// Visibility: uploaded private; "Set visibility" switched it if something else was wanted
let header = '🔒 <b>Uploaded as private</b>';
let outcome = 'uploaded_private';
if (m.privacy !== 'private') {
  const res = ran('Set visibility') ? $('Set visibility').first().json : {};
  const now = res.status && res.status.privacyStatus;
  const want = m.publishAt ? `schedule it for ${esc(m.publishAtLocal)}` : `make it ${esc(m.privacy)}`;
  if (res.error || !now) {
    header = `❌ <b>Uploaded as private, could not ${want}</b>\n`
      + esc(String((res.error && (res.error.message || res.error)) || 'no answer from YouTube').slice(0, 200));
    outcome = m.publishAt ? 'schedule_failed' : 'visibility_failed';
  } else if (m.publishAt) {
    if (now === 'private' && res.status.publishAt) {
      header = `🗓️ <b>Scheduled</b>: private until ${esc(m.publishAtLocal)}, then public`;
      outcome = 'scheduled';
    } else {
      header = `⚠️ <b>YouTube did not keep the publish date</b> (status ${esc(now)}). Set it in Studio.`;
      outcome = 'schedule_failed';
    }
  } else if (now === m.privacy) {
    header = m.privacy === 'public' ? '🌍 <b>Published</b>' : '🔗 <b>Uploaded as unlisted</b> (only people with the link)';
    outcome = m.privacy === 'public' ? 'published' : 'uploaded_unlisted';
  } else {
    header = `⚠️ <b>YouTube kept it ${esc(now)}</b> (wanted ${esc(m.privacy)}). Uploads from API projects `
      + "that have not passed YouTube's audit stay private; change it in Studio.";
    outcome = 'visibility_locked';
  }
}
const rv = m.related || {};
const desc = m.description.length > 700 ? m.description.slice(0, 699) + '…' : m.description;
const lines = [
  header,
  `<b>${esc(m.title)}</b>`,
  `${esc(m.channelName)} · ${m.isShort ? 'Short' : 'Video'} · ${Math.round(m.duration)} s`,
  '',
  `<i>Title:</i> ${from('title')}`,
  `<i>Description:</i> ${from('description')}`,
  `<i>Tags:</i> ${from('tags')}: ${esc(m.tagList.slice(0, 12).join(', '))}`,
  `<i>Thumbnail A:</i> ${thumbA}`,
  ...(thumbB ? [`<i>Thumbnail B:</i> ${thumbB}`] : []),
  ...(rv.ok
    ? [`<i>Linked video:</i> <a href="${rv.url}">${esc(rv.title || rv.id)}</a>, at the top of the description`
       + (m.isShort ? `. Shorts "Related video" has no API: pick it in Studio (id <code>${esc(rv.id)}</code>).` : '')
       + (rv.note ? ` ⚠️ ${esc(rv.note)}` : '')]
    : rv.mode && rv.mode !== 'none' ? [`<i>Linked video:</i> ⚠️ none added: ${esc(rv.note || 'lookup skipped')}`] : []),
  `<i>Visibility:</i> ${m.publishAt ? `public from ${esc(m.publishAtLocal)}` : esc(m.privacy)} (${esc(m.privacySource)})`,
  '',
  esc(desc),
  '',
  `<a href="${studio}">Open in YouTube Studio</a> · <a href="${watch}">Watch</a>`,
];
return [{ json: { text: lines.join('\n'), videoId, outcome } }];

// One CSV line per run: timestamp,channel,file,video_id,title,outcome,detail,execution_id
const m = $('Final metadata').first().json;
const videoId = $('Upload to YouTube (private)').first().json.uploadId;
const generated = ['title', 'description', 'tags'].filter((k) => m.source[k] === 'llm');
const outcome = $('Build reply').first().json.outcome;
const detail = 'telegram' + (generated.length ? ' generated ' + generated.join('+') : '') + ` wanted ${m.publishAt ? 'public at ' + m.publishAt : m.privacy}`
  + (m.related && m.related.ok ? ` linked ${m.related.id}` : '');
const q = (v) => `"${String(v ?? '').replace(/"/g, '""').replace(/\r?\n/g, ' ')}"`;
const line = [new Date().toISOString(), m.channel, q(m.fileName), videoId, q(m.title), outcome, q(detail), $execution.id].join(',') + '\n';
return [{ json: { line } }];

// A named video, or the newest public upload longer than 3 minutes (Shorts are 3 minutes at most)
const rel = $('Parse intake').first().json.related || {};
const errOf = (n) => { const j = $(n).first().json; return j.error ? (j.error.message || JSON.stringify(j.error)) : null; };
const err = ['Find uploads playlist', 'Latest uploads', 'Video details'].map(errOf).find(Boolean);
const items = $('Video details').first().json.items || [];
const secs = (iso) => {
  const m = /^P(?:(\d+)D)?T?(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?$/.exec(String(iso || '')) || [];
  return (+m[1] || 0) * 86400 + (+m[2] || 0) * 3600 + (+m[3] || 0) * 60 + (+m[4] || 0);
};
const out = (pick, note) => [{ json: pick
  ? { ok: true, id: pick.id, title: (pick.snippet || {}).title || '', url: `https://youtu.be/${pick.id}`,
      mode: rel.mode, source: rel.source, warning: note || null }
  : { ok: false, mode: rel.mode, source: rel.source, reason: note } }];

if (rel.mode === 'video') {
  const found = items.find((v) => v.id === rel.video_id);
  if (found) {
    const st = (found.status || {}).privacyStatus;
    return out(found, st && st !== 'public' ? `the linked video is ${st}` : null);
  }
  // not visible to this channel's API (another channel, deleted): link it anyway, without a title
  return out({ id: rel.video_id, snippet: {} }, err ? `could not check it: ${String(err).slice(0, 120)}` : 'could not check it');
}
const long = items
  .filter((v) => (v.status || {}).privacyStatus === 'public' && secs((v.contentDetails || {}).duration) > 180)
  .sort((a, b) => String((b.snippet || {}).publishedAt).localeCompare(String((a.snippet || {}).publishedAt)));
if (long.length) return out(long[0]);
return out(null, err ? `YouTube lookup failed: ${String(err).slice(0, 150)}`
  : 'no public video longer than 3 minutes among the last 50 uploads');
